package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.inventario.domain.model.*; @Entity @Table(name="inventory_holds") public class HoldJpaEntity {@Id UUID id; @Column(name="operation_key",nullable=false,unique=true,length=200) String operationKey; @Column(name="book_id",nullable=false,length=200) String bookId; @Column(nullable=false) int quantity; @Column(name="expires_at",nullable=false) Instant expiresAt; @Column(name="request_hash",nullable=false,length=64) String requestHash; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) InventoryState state; protected HoldJpaEntity(){} HoldJpaEntity(Hold h){apply(h);} Hold domain(){return new Hold(id,operationKey,bookId,quantity,expiresAt,requestHash,state);} void apply(Hold h){id=h.id();operationKey=h.operationKey();bookId=h.bookId();quantity=h.quantity();expiresAt=h.expiresAt();requestHash=h.requestHash();state=h.state();} }
